#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub enum OverrideKind {
    AllOff,
    Exempt,
    Timed,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub enum ChangeSource {
    User,
    Schedule,
    OneShot,
    Emergency,
    Migration,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum JournalKind {
    #[serde(rename_all = "camelCase")]
    ProfileOn { profile_id: ProfileId, source: ChangeSource },
    #[serde(rename_all = "camelCase")]
    ProfileOff { profile_id: ProfileId, source: ChangeSource },
    #[serde(rename_all = "camelCase")]
    OverrideStarted { r#override: OverrideKind },
    #[serde(rename_all = "camelCase")]
    OverrideEnded { r#override: OverrideKind },
    ReenabledAll,
    #[serde(rename_all = "camelCase")]
    Relaxed { profile_id: ProfileId, summary: Vec<String> },
    #[serde(rename_all = "camelCase")]
    ProfileDeleted { profile_id: ProfileId },
    #[serde(rename_all = "camelCase")]
    PoolUnlocked { pools: Vec<PoolRef>, minutes: u16 },
    EmergencyUsed,
    KeyPaired,
    KeyUnpaired,
    /// Written once when upgrading from a v5 state file.
    Migration,
}

/// Append-only, sync-ready event log. Ids are globally unique (`<deviceId>:<seq>`) so a future
/// account sync is a union merge; streak and emergency counts are pure functions of it.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[cfg_attr(feature = "ts", derive(ts_rs::TS))]
#[serde(rename_all = "camelCase")]
pub struct JournalEntry {
    pub id: String,
    pub device_id: String,
    #[cfg_attr(feature = "ts", ts(type = "number"))]
    pub seq: u64,
    #[cfg_attr(feature = "ts", ts(type = "number"))]
    pub at_ms: i64,
    pub local_date: String,
    /// Whether this entry resets the streak (key overrides, relaxations, emergency unlocks).
    pub breaks_streak: bool,
    pub kind: JournalKind,
}

impl EngineState {
    pub fn new(device_id: &str) -> Self {
        EngineState {
            schema: SCHEMA_VERSION,
            device_id: device_id.to_string(),
            profiles: Vec::new(),
            default_profile_id: None,
            overrides: Overrides::default(),
            pool_usage: Vec::new(),
            pending_unlocks: Vec::new(),
            journal: Vec::new(),
            journal_seq: 0,
            last_evaluated_ms: 0,
            first_enabled_local_date: None,
            generation: 0,
        }
    }

    pub fn profile(&self, id: &str) -> Option<&Profile> {
        self.profiles.iter().find(|p| p.id == id)
    }

    pub fn profile_mut(&mut self, id: &str) -> Option<&mut Profile> {
        self.profiles.iter_mut().find(|p| p.id == id)
    }

    pub fn pool(&self, r: &PoolRef) -> Option<&Pool> {
        self.profile(&r.profile_id)?.config.pools.iter().find(|p| p.id == r.pool_id)
    }
}
